const trading = $('JARVIS — Get Trading Status').first().json;
const prices = $('CoinGecko — Prix Trading Pairs').first().json;

const now = new Date();
const timeStr = now.toLocaleTimeString('fr-FR');

// Prix pairs
const pairs = [
  { id: 'bitcoin', symbol: '₿ BTC' },
  { id: 'ethereum', symbol: 'Ξ ETH' },
  { id: 'solana', symbol: '◎ SOL' },
  { id: 'sui', symbol: '🔵 SUI' },
  { id: 'pepe', symbol: '🐸 PEPE' },
  { id: 'dogecoin', symbol: '🐕 DOGE' }
];

let priceLines = '';
if (prices) {
  priceLines = pairs.map(p => {
    const d = prices[p.id];
    if (!d) return null;
    const change = d.usd_24h_change?.toFixed(2);
    const arrow = change >= 0 ? '📈' : '📉';
    const vol = d.usd_24h_vol ? `Vol: $${(d.usd_24h_vol/1e9).toFixed(2)}B` : '';
    return `  ${p.symbol}: $${d.usd < 1 ? d.usd.toFixed(6) : d.usd.toLocaleString()} ${arrow}${change}% ${vol}`;
  }).filter(Boolean).join('\n');
}

// Trading status
let tradingStatus = '';
if (trading && !trading.error) {
  tradingStatus = `\n📊 *Trading Bot:* ${trading.status || 'Actif'}\nPositions: ${trading.positions || 0} | PnL: ${trading.pnl || 'N/A'}`;
} else {
  tradingStatus = `\n📊 *Trading Bot:* Hors ligne (port 9742)`;
}

const message = `📈 *JARVIS Trading Monitor — ${timeStr}*\n\n💱 *Marchés MEXC Futures:*\n${priceLines}${tradingStatus}\n\n━━━━━━━━━━━━━━━━\n_Scan toutes les 15min — DRY_RUN check_`;

return [{ json: { message, prices, hasAlert: false } }];
